contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public {
        require(loanToCollateral_ != 0);
        require(amount_ != 0);

        c.requestLoan(amount_, interest_, loanToCollateral_, duration_); if (__ESBMC_reverted()) return;

        bool firstReverted;
        c.clearRequest(0, false, false); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        bool secondReverted;
        c.clearRequest(0, false, false); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = true;
        }

        assert(!firstReverted && secondReverted && !c.isActive(0));
    }
}

