// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) internal {
        vm.assume(loanToCollateral_ != 0);
        vm.assume(amount_ != 0);
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {} catch { return; }
        bool firstReverted;
        try c.clearRequest(0, false, false) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        bool secondReverted;
        try c.clearRequest(0, false, false) {
            secondReverted = true;
        } catch {
            secondReverted = true;
        }
        assertTrue(!firstReverted && secondReverted && !c.isActive(0));
    }

    function testFuzz_run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public {
        _run(amount_, interest_, loanToCollateral_, duration_);
    }

    receive() external payable {}
}
